SELECT recharge_id, user_id, amount, request_id, status, created_at
FROM recharge_record
WHERE request_id = #{requestId}

SELECT recharge_id, user_id, amount, request_id, status, created_at
FROM recharge_record
WHERE user_id = #{userId}
ORDER BY created_at DESC
LIMIT #{offset}, #{limit}

SELECT COUNT(*)
FROM recharge_record
WHERE user_id = #{userId}
